Assuming your posts are stored in a file or a directory named "posts" in the same directory as your HTML files (`/usr/share/nginx/html/posts`), you can add a piece of code in your existing Nginx configuration.

Here's an updated example:
```nginx
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name www.askfundu.com;
    root /usr/share/nginx/html;

    # ... (keep all the existing configuration)

    location / {
        root /usr/share/nginx/html;
        index index.html index.htm;
        try_files $uri $uri/ /index.html;

        # Add a link to each post
        if ($uri ~ "(.*).html" || $uri ~ "(.*)/") {
            set $post_title "";
            set $post_link "";
            if ($uri ~ "(.*).html") {
                set $post_title $uri;
                set $post_link "</a><a href=\"$uri\"><h2>$post_title</h2>";
            } elseif ($uri ~ "(.*)/") {
                set $post_title idx $uri;
                set $post_link "</a><a href=\"$uri\"><h2>$post_title</h2>";
            }
            echo "$post_link";
        }
    }

    # ... (keep all the existing error pages and other configurations)
}
```
